/**
 * Practice tasks for a target role (20261108090600). Fixed templates, filled with one workbook skill and the candidate's
 * target. Nothing here is generated by a model, and nothing claims to be real work: a simulated task is practice, and a
 * portfolio project is the candidate's own work. The checklist reads only the submission's shape, never its quality.
 */
export const PRACTICE_TEMPLATE_VERSION = 'practice-v1';
export type PracticeKind = 'simulated_task' | 'portfolio_project';
type Text = { ar: string; en: string };

export function practiceTask(kind: PracticeKind, skill: string, role: string | null) {
  const forRole = role ? { ar: ` لدور «${role}»`, en: ` for the role "${role}"` } : { ar: '', en: '' };
  if (kind === 'simulated_task') {
    return {
      kind,
      template_version: PRACTICE_TEMPLATE_VERSION,
      title_ar: `مهمة محاكاة: تطبيق «${skill}»`,
      title_en: `Simulated task: applying "${skill}"`,
      brief_ar: `موقف عمل خيالي${forRole.ar} يحتاج إلى «${skill}». هذه مهمة للتدرّب فقط: ليست وظيفة ولا خبرة عمل، ولم تطلبها جهة.`,
      brief_en: `A fictional work situation${forRole.en} that needs "${skill}". It's practice only: not a job, not work experience, and no organization asked for it.`,
      instructions: [
        { ar: 'اختاروا موقفًا واقعيًا يحتاج إلى هذه المهارة، وصفوه في فقرة.', en: 'Pick a realistic situation that needs this skill, and describe it in a paragraph.' },
        { ar: 'اشرحوا خطوات عملكم كما لو كنتم تنفذونها، مع سبب كل خطوة.', en: 'Explain the steps you would take, and why each one.' },
        { ar: 'اختموا بما ستتحققون منه لتعرفوا أن العمل نجح.', en: 'End with what you would check to know the work succeeded.' },
      ] satisfies Text[],
      deliverables: [
        { ar: 'وصف الموقف', en: 'The situation' },
        { ar: 'الخطوات وأسبابها', en: 'The steps and why' },
        { ar: 'كيف تتحققون من النتيجة', en: 'How you would check the result' },
      ] satisfies Text[],
    };
  }
  return {
    kind,
    template_version: PRACTICE_TEMPLATE_VERSION,
    title_ar: `مشروع لملف أعمالكم: «${skill}»`,
    title_en: `Portfolio project: "${skill}"`,
    brief_ar: `مشروع صغير تنفذونه بأنفسكم${forRole.ar} ليُظهر «${skill}». هو عملكم الخاص، لا خبرة عمل لدى جهة.`,
    brief_en: `A small project you carry out yourself${forRole.en} to show "${skill}". It's your own work, not work experience with an organization.`,
    instructions: [
      { ar: 'حددوا مشكلة صغيرة يمكن حلها في أيام قليلة باستخدام هذه المهارة.', en: 'Choose a small problem you can solve in a few days with this skill.' },
      { ar: 'نفذوا الحل، واحفظوه في مكان يمكن مشاركته برابط.', en: 'Build the solution, and keep it somewhere you can share with a link.' },
      { ar: 'اكتبوا ما فعلتم وما تعلمتم وما ستغيرونه.', en: 'Write up what you did, what you learned and what you would change.' },
    ] satisfies Text[],
    deliverables: [
      { ar: 'المشكلة', en: 'The problem' },
      { ar: 'ما نفذتموه', en: 'What you built' },
      { ar: 'ما تعلمتموه', en: 'What you learned' },
      { ar: 'رابط العمل', en: 'A link to the work' },
    ] satisfies Text[],
  };
}

export type Check = { code: 'enough_detail' | 'each_deliverable' | 'names_skill' | 'has_link'; met: boolean };

/** MIDAN's checklist on a submission's shape. It isn't an assessment of quality, and it is labelled as such. */
export function practiceChecklist(kind: PracticeKind, skill: string, submission: string, url: string | null, deliverables: number): Check[] {
  const words = submission.trim().split(/\s+/).filter(Boolean).length;
  const paragraphs = submission.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean).length;
  const checks: Check[] = [
    { code: 'enough_detail', met: words >= 120 },
    { code: 'each_deliverable', met: paragraphs >= deliverables - (kind === 'portfolio_project' ? 1 : 0) },
    { code: 'names_skill', met: submission.toLowerCase().includes(skill.trim().toLowerCase()) },
  ];
  if (kind === 'portfolio_project') checks.push({ code: 'has_link', met: Boolean(url) });
  return checks;
}
